  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	import java.math.RoundingMode;
  9	import java.time.DayOfWeek;
 10	import java.time.LocalDate;
 11	import java.time.temporal.ChronoUnit;
 12	
 13	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 14	public final class ReservationService {
 15	
 16	    static final String HOTEL_NAME = "Pousada Maré Alta";
 17	
 18	    private final Rooms rooms;
 19	    private final ReservationStore store;
 20	    private final PriceCalculator priceCalculator;
 21	    private final EmailSender emailSender;
 22	
 23	    public ReservationService(
 24	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 25	        this.rooms = rooms;
 26	        this.store = store;
 27	        this.priceCalculator = priceCalculator;
 28	        this.emailSender = emailSender;
 29	    }
 30	
 31	    public synchronized Reservation create(NewReservation request) {
 32	        if (!request.checkOut().isAfter(request.checkIn())) {
 33	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 34	        }
 35	        if (request.guests() < 1) {
 36	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 37	        }
 38	        Room room = rooms.find(request.roomNumber())
 39	                .orElseThrow(() -> new HotelException(
 40	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 41	        if (request.guests() > room.capacity()) {
 42	            throw new HotelException(
 43	                    ErrorCode.CAPACITY_EXCEEDED,
 44	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 45	        }
 46	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 47	            throw new HotelException(
 48	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 49	        }
 50	
 51	        validateRatePlanRequirements(request);
 52	
 53	        Price price = priceCalculator.calculate(
 54	                room, request.checkIn(), request.checkOut(), request.ratePlan(), request.companyCode());
 55	        return store.add(request, price);
 56	    }
 57	
 58	    private void validateRatePlanRequirements(NewReservation request) {
 59	        switch (request.ratePlan()) {
 60	            case CORPORATE:
 61	                if (request.companyCode() == null
 62	                        || !CompanyDiscount.isValid(request.companyCode())) {
 63	                    throw new HotelException(
 64	                            ErrorCode.INVALID_REQUEST, "invalid or missing company code for corporate plan");
 65	                }
 66	                break;
 67	            case WEEKEND_PACKAGE:
 68	                if (!isWeekendPackageDateValid(request.checkIn(), request.checkOut())) {
 69	                    throw new HotelException(
 70	                            ErrorCode.INVALID_REQUEST,
 71	                            "weekend package must be Friday to Sunday (exactly 2 nights)");
 72	                }
 73	                break;
 74	            case LONG_STAY:
 75	                int nights = (int) ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
 76	                if (nights < 7) {
 77	                    throw new HotelException(
 78	                            ErrorCode.INVALID_REQUEST, "long stay plan requires at least 7 nights");
 79	                }
 80	                break;
 81	            case STANDARD, NON_REFUNDABLE:
 82	                break;
 83	        }
 84	    }
 85	
 86	    private boolean isWeekendPackageDateValid(LocalDate checkIn, LocalDate checkOut) {
 87	        if (checkOut.minusDays(2).compareTo(checkIn) != 0) {
 88	            return false;
 89	        }
 90	        DayOfWeek dayOfWeek = checkIn.getDayOfWeek();
 91	        return dayOfWeek == DayOfWeek.FRIDAY;
 92	    }
 93	
 94	    public Reservation find(long reservationId) {
 95	        return store.find(reservationId)
 96	                .orElseThrow(() -> new HotelException(
 97	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 98	    }
 99	
100	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
101	    public synchronized Reservation confirm(long reservationId) {
102	        Reservation reservation = find(reservationId);
103	        if (reservation.status() != ReservationStatus.PENDING) {
104	            throw notAllowed(reservation, "confirm");
105	        }
106	        reservation.confirmPayment();
107	        store.update(reservation);
108	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
109	        emailSender.send(
110	                reservation.guest().email(),
111	                "Reserva confirmada - " + HOTEL_NAME,
112	                confirmationEmailBody(reservation, receipt));
113	        return reservation;
114	    }
115	
116	    /**
117	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
118	     * reservation was never paid, so nothing comes back).
119	     */
120	    public synchronized Reservation cancel(long reservationId) {
121	        Reservation reservation = find(reservationId);
122	        if (reservation.status() != ReservationStatus.PENDING
123	                && reservation.status() != ReservationStatus.CONFIRMED) {
124	            throw notAllowed(reservation, "cancel");
125	        }
126	        BigDecimal refund = switch (reservation.ratePlan()) {
127	            case STANDARD, CORPORATE, LONG_STAY -> reservation.amountPaid();
128	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
129	            case WEEKEND_PACKAGE -> PriceCalculator.cents(reservation.amountPaid().divide(
130	                    BigDecimal.TWO, 2, RoundingMode.HALF_EVEN));
131	        };
132	        reservation.cancel(refund);
133	        store.update(reservation);
134	        return reservation;
135	    }
136	
137	    public synchronized Reservation checkIn(long reservationId) {
138	        Reservation reservation = find(reservationId);
139	        if (reservation.status() != ReservationStatus.CONFIRMED) {
140	            throw notAllowed(reservation, "check in");
141	        }
142	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
143	        store.update(reservation);
144	        return reservation;
145	    }
146	
147	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
148	    public synchronized ReservationReceipt checkOut(long reservationId) {
149	        Reservation reservation = find(reservationId);
150	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
151	            throw notAllowed(reservation, "check out");
152	        }
153	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
154	        store.update(reservation);
155	        return new ReservationReceipt(reservation, roomOf(reservation));
156	    }
157	
158	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
159	    public ReservationReceipt receiptCopy(long reservationId) {
160	        Reservation reservation = find(reservationId);
161	        if (!reservation.isPaid()) {
162	            throw notAllowed(reservation, "issue a receipt for");
163	        }
164	        return new ReservationReceipt(reservation, roomOf(reservation));
165	    }
166	
167	    private Room roomOf(Reservation reservation) {
168	        return rooms.find(reservation.roomNumber()).orElseThrow();
169	    }
170	
171	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
172	        return "Olá, " + reservation.guest().name() + "!\n\n"
173	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
174	                + receipt.text() + "\n"
175	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
176	                + "Até breve!\n";
177	    }
178	
179	    private static HotelException notAllowed(Reservation reservation, String operation) {
180	        return new HotelException(
181	                ErrorCode.OPERATION_NOT_ALLOWED,
182	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
183	    }
184	}
  1	package hotel.reservations;
  2	
  3	import hotel.rooms.Room;
  4	import java.math.BigDecimal;
  5	import java.math.RoundingMode;
  6	import java.time.DayOfWeek;
  7	import java.time.LocalDate;
  8	import java.time.Month;
  9	
 10	/**
 11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 13	 * (half-even) at every step.
 14	 */
 15	public final class PriceCalculator {
 16	
 17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 19	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 20	
 21	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 22	        return calculate(room, checkIn, checkOut, ratePlan, null);
 23	    }
 24	
 25	    public Price calculate(
 26	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 27	        return switch (ratePlan) {
 28	            case STANDARD -> calculateStandard(room, checkIn, checkOut);
 29	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut);
 30	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
 31	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 32	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
 33	        };
 34	    }
 35	
 36	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut) {
 37	        int nights = 0;
 38	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 39	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 40	            subtotal = subtotal.add(nightPrice(room, night));
 41	            nights++;
 42	        }
 43	        return new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
 44	    }
 45	
 46	    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut) {
 47	        int nights = 0;
 48	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 49	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 50	            subtotal = subtotal.add(nightPrice(room, night));
 51	            nights++;
 52	        }
 53	        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 54	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 55	    }
 56	
 57	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 58	        int nights = 0;
 59	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 60	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 61	            subtotal = subtotal.add(nightPrice(room, night));
 62	            nights++;
 63	        }
 64	        BigDecimal discountRate = CompanyDiscount.discountFor(companyCode);
 65	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 66	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 67	    }
 68	
 69	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
 70	        BigDecimal price = WeekendPackagePrice.priceFor(room.type());
 71	        return new Price(2, price, cents(BigDecimal.ZERO), price);
 72	    }
 73	
 74	    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut) {
 75	        int nights = 0;
 76	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 77	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 78	            subtotal = subtotal.add(nightPrice(room, night));
 79	            nights++;
 80	        }
 81	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 82	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 83	    }
 84	
 85	    BigDecimal nightPrice(Room room, LocalDate night) {
 86	        BigDecimal nightlyRate = room.nightlyRate();
 87	        if (isHighSeason(night)) {
 88	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 89	        }
 90	        return cents(nightlyRate);
 91	    }
 92	
 93	    /** High season: from December 15 to the end of February, and the whole of July. */
 94	    static boolean isHighSeason(LocalDate date) {
 95	        Month month = date.getMonth();
 96	        return month == Month.JANUARY
 97	                || month == Month.FEBRUARY
 98	                || month == Month.JULY
 99	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
100	    }
101	
102	    static BigDecimal cents(BigDecimal value) {
103	        return value.setScale(2, RoundingMode.HALF_EVEN);
104	    }
105	}
