162	            throw notAllowed(reservation, "issue a receipt for");
163	        }
164	        return new ReservationReceipt(reservation, roomOf(reservation));
165	    }
166	
167	    private Room roomOf(Reservation reservation) {
168	        return rooms.find(reservation.roomNumber()).orElseThrow();
169	    }
170	
171	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
172	        return "Olá, " + reservation.guest().name() + "!\n\n"
173	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
174	                + receipt.text() + "\n"
175	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
176	                + "Até breve!\n";
177	    }
178	
179	    private static HotelException notAllowed(Reservation reservation, String operation) {
180	        return new HotelException(
181	                ErrorCode.OPERATION_NOT_ALLOWED,
182	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
183	    }
