  2	
  3	import hotel.rooms.Room;
  4	import java.math.BigDecimal;
  5	import java.math.RoundingMode;
  6	import java.time.DayOfWeek;
  7	import java.time.LocalDate;
  8	import java.time.Month;
  9	
 10	/**
 11	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
 12	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
 13	 * (half-even) at every step.
 14	 */
 15	public final class PriceCalculator {
 16	
 17	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
 18	    static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
 19	    static final BigDecimal LONG_STAY_DISCOUNT = new BigDecimal("0.10");
 20	
 21	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan) {
 22	        return calculate(room, checkIn, checkOut, ratePlan, null);
 23	    }
 24	
 25	    public Price calculate(
 26	            Room room, LocalDate checkIn, LocalDate checkOut, RatePlan ratePlan, String companyCode) {
 27	        return switch (ratePlan) {
 28	            case STANDARD -> calculateStandard(room, checkIn, checkOut);
 29	            case NON_REFUNDABLE -> calculateNonRefundable(room, checkIn, checkOut);
 30	            case CORPORATE -> calculateCorporate(room, checkIn, checkOut, companyCode);
 31	            case WEEKEND_PACKAGE -> calculateWeekendPackage(room, checkIn, checkOut);
 32	            case LONG_STAY -> calculateLongStay(room, checkIn, checkOut);
 33	        };
 34	    }
 35	
 36	    private Price calculateStandard(Room room, LocalDate checkIn, LocalDate checkOut) {
 37	        int nights = 0;
 38	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 39	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 40	            subtotal = subtotal.add(nightPrice(room, night));
 41	            nights++;
 42	        }
 43	        return new Price(nights, subtotal, cents(BigDecimal.ZERO), subtotal);
 44	    }
 45	
 46	    private Price calculateNonRefundable(Room room, LocalDate checkIn, LocalDate checkOut) {
 47	        int nights = 0;
 48	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 49	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 50	            subtotal = subtotal.add(nightPrice(room, night));
 51	            nights++;
 52	        }
 53	        BigDecimal discount = cents(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
 54	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 55	    }
 56	
 57	    private Price calculateCorporate(Room room, LocalDate checkIn, LocalDate checkOut, String companyCode) {
 58	        int nights = 0;
 59	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 60	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 61	            subtotal = subtotal.add(nightPrice(room, night));
 62	            nights++;
 63	        }
 64	        BigDecimal discountRate = CompanyDiscount.discountFor(companyCode);
 65	        BigDecimal discount = cents(subtotal.multiply(discountRate));
 66	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 67	    }
 68	
 69	    private Price calculateWeekendPackage(Room room, LocalDate checkIn, LocalDate checkOut) {
 70	        BigDecimal price = WeekendPackagePrice.priceFor(room.type());
 71	        return new Price(2, price, cents(BigDecimal.ZERO), price);
 72	    }
 73	
 74	    private Price calculateLongStay(Room room, LocalDate checkIn, LocalDate checkOut) {
 75	        int nights = 0;
 76	        BigDecimal subtotal = cents(BigDecimal.ZERO);
 77	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
 78	            subtotal = subtotal.add(nightPrice(room, night));
 79	            nights++;
 80	        }
 81	        BigDecimal discount = cents(subtotal.multiply(LONG_STAY_DISCOUNT));
 82	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
 83	    }
 84	
 85	    BigDecimal nightPrice(Room room, LocalDate night) {
 86	        BigDecimal nightlyRate = room.nightlyRate();
 87	        if (isHighSeason(night)) {
 88	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
 89	        }
 90	        return cents(nightlyRate);
 91	    }
 92	
 93	    /** High season: from December 15 to the end of February, and the whole of July. */
 94	    static boolean isHighSeason(LocalDate date) {
 95	        Month month = date.getMonth();
 96	        return month == Month.JANUARY
 97	                || month == Month.FEBRUARY
 98	                || month == Month.JULY
 99	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
100	    }
101	
102	    static BigDecimal cents(BigDecimal value) {
103	        return value.setScale(2, RoundingMode.HALF_EVEN);
104	    }
105	}
